import { maakSom, type Redactiesom, type Stap } from './types';

/**
 * De huiswerkbladen, precies zoals ze op papier staan.
 *
 * Elk blad komt uit de map van groep 7: dezelfde tekst, dezelfde getallen en
 * dezelfde volgorde, zodat een kind thuis het blad van deze week terugvindt
 * en zijn antwoorden kan vergelijken. De bladnummers staan onderaan het
 * papier; de bladen zonder nummer zijn op moeilijkheid in de gaten gezet.
 *
 * Een stap is: [wat je doet, de som, het antwoord, de eenheid, de tip].
 * Een kloktijd of een keuze is geen som die na te rekenen is; die heeft een
 * vast antwoord (zie `Stap.soort` en `Stap.keuzes`).
 */
export interface Blad { nr: number; sommen: Redactiesom[] }

type Regel = [vraag: string, som: string, antwoord: number, eenheid: string, tip: string, extra?: Partial<Stap>];
const euro: Partial<Stap> = { soort: 'euro' };
const klok: Partial<Stap> = { soort: 'tijd', verborgen: true };

function som(blad: number, nr: number, deel: {
  verhaal: string; nodig: string[]; zoek: string; stappen: Regel[]; controle: string; aanpak: string; type?: string; beeld?: string;
}): Redactiesom {
  const stappen = deel.stappen.map(([vraag, som, antwoord, eenheid, tip, extra]) => ({ vraag, som, antwoord, eenheid, tip, ...extra }));
  const vraag = maakSom({
    typeId: deel.type ?? 'blad', id: `blad:${blad}:${nr}`, verhaal: deel.verhaal, nodig: deel.nodig,
    zoek: deel.zoek, stappen, controle: deel.controle, aanpak: deel.aanpak,
  });
  return deel.beeld ? { ...vraag, beeld: deel.beeld } : vraag;
}

